    'Terminal' => 'Терминал',
    'The app-relative path MCP clients connect to, such as `/mcp`.' => 'MCP кардарлары туташа турган тиркемеге салыштырмалуу жол, мисалы, `/mcp`.',
    'The app-relative path public MCP clients connect to, such as `/mcp`.' => 'Ачык MCP кардарлары туташа турган тиркемеге салыштырмалуу жол, мисалы, `/mcp`.',
    'The app-relative path to give MCP clients that sign in with OAuth. It always requires an access token, so clients can discover how to sign in.' => 'OAuth аркылуу кирген MCP кардарларына берилүүчү тиркемеге салыштырмалуу жол. Ал ар дайым кирүү токенин талап кылат, ошентип кардарлар кантип кирүүнү биле алышат.',
    'The authenticated server uses this endpoint too. Requests without an access token go to the public server, so MCP clients can’t discover how to sign in at this endpoint.' => 'Аутентификацияланган сервер да бул акыркы чекитти колдонот. Кирүү токени жок сурамдар ачык серверге жөнөтүлөт, ошондуктан MCP кардарлары бул акыркы чекитте кантип кирүүнү биле алышпайт.',
    'The condition isn’t valid.' => 'Шарт жараксыз.',
    'The draft can’t be added to a scheduled release until it’s ready to publish: {errors}' => 'Долбоор жарыялоого даяр болмоюнча аны пландаштырылган релизге кошууга болбойт: {errors}',
