    'The minimum number of approvals required in total or per reviewer group.' => 'Жалпы же ар бир карап чыгуучулар тобу үчүн талап кылынган бекитүүлөрдүн минималдуу саны.',
    'The navigation everyone gets. User group navigations build on it.' => 'Баарына көрсөтүлүүчү навигация. Колдонуучулар топторунун навигациялары анын негизинде түзүлөт.',
