    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to search and read this site’s public content in plain language.' => 'Бул URL веб-барак эмес, AI жардамчылары үчүн MCP сервери. Бул сайттын ачык мазмунун жөнөкөй тил менен издөө жана окуу үчүн аны жардамчыңызга кошуңуз.',
    'This URL is an MCP server for AI assistants, not a web page. Add it to your assistant to work with this site’s content and settings in plain language.' => 'Бул URL веб-барак эмес, AI жардамчылары үчүн MCP сервери. Бул сайттын мазмуну жана жөндөөлөрү менен жөнөкөй тилде иштөө үчүн аны жардамчыңызга кошуңуз.',
    'This application will be able to:' => 'Бул тиркеме төмөнкүлөрдү жасай алат:',
