    'The {numRelations, plural, =1{relation} other {relations}} will be removed once the {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} deleted.' => '{numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}} өчүрүлгөндөн кийин {numRelations, plural, =1{байланыш} other {байланыштар}} алынып салынат.',
    'The {numTargets, plural, =1{{targetTypeSingular} is} other{{targetTypePlural} are}} referenced by fields in {numSources, number} other {numSources, plural, =1{element} other{elements}}.' => '{numTargets, plural, =1{{targetTypeSingular}} other{{targetTypePlural}}} башка {numSources, number} {numSources, plural, =1{элементтин} other{элементтин}} талааларында шилтеме катары колдонулат.',
